package com.javaweb.controller.web;

import com.javaweb.model.request.BuildingSearchRequest;
import com.javaweb.utils.DistrictCode;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.web.authentication.logout.SecurityContextLogoutHandler;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.servlet.ModelAndView;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.http.HttpSession;

@Controller(value = "homeControllerOfWeb")
public class HomeController {

	@RequestMapping(value = "/trang-chu", method = RequestMethod.GET)
	public ModelAndView homePage(BuildingSearchRequest buildingSearchRequest, HttpServletRequest request) {
		ModelAndView mav = new ModelAndView("web/home");
        mav.addObject("modelSearch", buildingSearchRequest);
        mav.addObject("districts", DistrictCode.type());
		return mav;
	}

    @GetMapping(value="/gioi-thieu")
    public ModelAndView introducceBuiding(){
        ModelAndView mav = new ModelAndView("web/introduce");
        return mav;
    }

    @GetMapping(value="/san-pham")
    public ModelAndView buidingList(){
        ModelAndView mav = new ModelAndView("/web/list");
        return mav;
    }

    @GetMapping(value="/tin-tuc")
    public ModelAndView news(){
        ModelAndView mav = new ModelAndView("/web/news");
        return mav;
    }

    @GetMapping(value="/lien-he")
    public ModelAndView contact(){
        ModelAndView mav = new ModelAndView("/web/contact");
        return mav;
    }

	@RequestMapping(value = "/login", method = RequestMethod.GET)
	public ModelAndView login() {
		ModelAndView mav = new ModelAndView("login");
		return mav;
	}

	@RequestMapping(value = "/access-denied", method = RequestMethod.GET)
	public ModelAndView accessDenied() {
		return new ModelAndView("redirect:/login?accessDenied");
	}

	@RequestMapping(value = "/logout", method = RequestMethod.GET)
	public ModelAndView logout(HttpServletRequest request, HttpServletResponse response, HttpSession session) {
		Authentication auth = SecurityContextHolder.getContext().getAuthentication();
		if (auth != null) {
			new SecurityContextLogoutHandler().logout(request, response, auth);
		}
		return new ModelAndView("redirect:/trang-chu");
	}

    @RequestMapping(value = "/register", method = RequestMethod.GET)
    public ModelAndView register() {
        ModelAndView mav = new ModelAndView("register");
        return mav;
    }


}

package com.javaweb.controller.web;

import com.javaweb.enums.District;
import com.javaweb.enums.TypeCode;
import com.javaweb.model.request.BuildingSearchRequest;
import com.javaweb.model.response.BuildingSearchResponse;
import com.javaweb.service.BuildingService;
import com.javaweb.utils.ProvinceCode;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Pageable;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.web.authentication.logout.SecurityContextLogoutHandler;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.servlet.ModelAndView;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.util.Collections;
import java.util.List;

@Controller(value = "homeControllerOfWeb")
public class HomeController {

  @Autowired
  private BuildingService buildingService;

  @RequestMapping(value = "/trang-chu", method = RequestMethod.GET)
  public ModelAndView homePage(BuildingSearchRequest buildingSearchRequest) {
		ModelAndView mav = new ModelAndView("web/home");
        mav.addObject("modelSearch", buildingSearchRequest);
        addFilterOptions(mav);
        mav.addObject("selectedProvince", "TP_HCM");
    mav.addObject("buildings", loadBuildings(buildingSearchRequest, 3));
		return mav;
	}

    @GetMapping(value="/gioi-thieu")
    public ModelAndView introducceBuiding(){
        return new ModelAndView("web/introduce");
    }

    @GetMapping(value="/san-pham")
    public ModelAndView buidingList(BuildingSearchRequest buildingSearchRequest,
                                    @RequestParam(value = "province", required = false, defaultValue = "TP_HCM") String province){
        ModelAndView mav = new ModelAndView("/web/list");
        mav.addObject("modelSearch", buildingSearchRequest);
        addFilterOptions(mav);
        mav.addObject("selectedProvince", province);
        mav.addObject("buildings", loadBuildings(buildingSearchRequest, 12));
        return mav;
    }

    @GetMapping(value="/tin-tuc")
    public ModelAndView news(){
        return new ModelAndView("/web/news");
    }

    @GetMapping(value="/lien-he")
    public ModelAndView contact(){
        return new ModelAndView("/web/contact");
    }

	@RequestMapping(value = "/login", method = RequestMethod.GET)
	public ModelAndView login() {
    return new ModelAndView("login");
	}

	@RequestMapping(value = "/access-denied", method = RequestMethod.GET)
	public ModelAndView accessDenied() {
		return new ModelAndView("redirect:/login?accessDenied");
	}

	@RequestMapping(value = "/logout", method = RequestMethod.GET)
  public ModelAndView logout(HttpServletRequest request, HttpServletResponse response) {
		Authentication auth = SecurityContextHolder.getContext().getAuthentication();
		if (auth != null) {
			new SecurityContextLogoutHandler().logout(request, response, auth);
		}
		return new ModelAndView("redirect:/trang-chu");
	}

    @RequestMapping(value = "/register", method = RequestMethod.GET)
    public ModelAndView register() {
		return new ModelAndView("register");
    }

      private List<BuildingSearchResponse> loadBuildings(BuildingSearchRequest buildingSearchRequest, int size) {
        try {
          Pageable pageable = PageRequest.of(0, size);
          List<BuildingSearchResponse> buildings = buildingService.findAll(buildingSearchRequest, pageable);
          return buildings != null ? buildings : Collections.emptyList();
        } catch (Exception e) {
          return Collections.emptyList();
        }
      }

      private void addFilterOptions(ModelAndView mav) {
        mav.addObject("provinces", ProvinceCode.getProvince());
        mav.addObject("districts", District.getDistrict());
        mav.addObject("typeCodes", TypeCode.getType());
      }


}

package com.javaweb.utils;
import java.util.LinkedHashMap; import java.util.Map;
public enum ProvinceCode { AN_GIANG("An Giang"), BA_RIA_VUNG_TAU("Ba Ria - Vung Tau"), BAC_GIANG("Bac Giang"), BAC_KAN("Bac Kan"), BAC_LIEU("Bac Lieu"), BAC_NINH("Bac Ninh"), BEN_TRE("Ben Tre"), BINH_DINH("Binh Dinh"), BINH_DUONG("Binh Duong"), BINH_PHUOC("Binh Phuoc"), BINH_THUAN("Binh Thuan"), CA_MAU("Ca Mau"), CAN_THO("Can Tho"), CAO_BANG("Cao Bang"), DA_NANG("Da Nang"), DAK_LAK("Dak Lak"), DAK_NONG("Dak Nong"), DIEN_BIEN("Dien Bien"), DONG_NAI("Dong Nai"), DONG_THAP("Dong Thap"), GIA_LAI("Gia Lai"), HA_GIANG("Ha Giang"), HA_NAM("Ha Nam"), HA_NOI("Ha Noi"), HA_TINH("Ha Tinh"), HAI_DUONG("Hai Duong"), HAI_PHONG("Hai Phong"), HAU_GIANG("Hau Giang"), HOA_BINH("Hoa Binh"), HUNG_YEN("Hung Yen"), KHANH_HOA("Khanh Hoa"), KIEN_GIANG("Kien Giang"), KON_TUM("Kon Tum"), LAI_CHAU("Lai Chau"), LAM_DONG("Lam Dong"), LANG_SON("Lang Son"), LAO_CAI("Lao Cai"), LONG_AN("Long An"), NAM_DINH("Nam Dinh"), NGHE_AN("Nghe An"), NINH_BINH("Ninh Binh"), NINH_THUAN("Ninh Thuan"), PHU_THO("Phu Tho"), PHU_YEN("Phu Yen"), QUANG_BINH("Quang Binh"), QUANG_NAM("Quang Nam"), QUANG_NGAI("Quang Ngai"), QUANG_NINH("Quang Ninh"), QUANG_TRI("Quang Tri"), SOC_TRANG("Soc Trang"), SON_LA("Son La"), TAY_NINH("Tay Ninh"), THAI_BINH("Thai Binh"), THAI_NGUYEN("Thai Nguyen"), THANH_HOA("Thanh Hoa"), THUA_THIEN_HUE("Thua Thien Hue"), TIEN_GIANG("Tien Giang"), TP_HCM("TP Ho Chi Minh"), TRA_VINH("Tra Vinh"), TUYEN_QUANG("Tuyen Quang"), VINH_LONG("Vinh Long"), VINH_PHUC("Vinh Phuc"), YEN_BAI("Yen Bai");
private final String provinceName;
ProvinceCode(String provinceName) { this.provinceName = provinceName; }
public String getProvinceName() { return provinceName; }
public static Map<String, String> getProvince() { Map<String, String> provinces = new LinkedHashMap<String, String>(); for (ProvinceCode item : ProvinceCode.values()) { provinces.put(item.toString(), item.getProvinceName()); } return provinces; } }

