  content: "Mới đăng";
  position: absolute;
  background-color: #FB6B26;
  width: 4.8rem;
  height: 1.6rem;
  border-radius: 8rem;
  top: 0.8rem;
  left: 0.8rem;
  color: white;
  font-size: 0.8rem;
  text-align: center;
  font-weight: 600;
  line-height: 1.4rem;
}

.hot::before {
  content: "hot";
  position: absolute;
  background-color: #3fdd00;
  right: 0.6rem;
  width: 3rem;
  height: 2.6rem;
  text-align: center;
  text-transform: uppercase;
  color: white;
  font-weight: 700;
  line-height: 2rem;
  animation: 0.5s linear 1s infinite reverse flicker;
}

.hot::after {
  content: "";
  position: absolute;
  top: 1.6rem;
  right: 0.6rem;
  border: 1rem solid;
  border-width: 1rem 1.5rem;
  border-color: transparent #3fdd00;
}

@keyframes flicker {
  0% {
    color: rgb(34, 0, 255);
  }

  50% {
    color: #35BF76;
  }
  100% {
    color: red;
  }
}

.vip::before {
  content: "vip";
  position: absolute;
  background-color: #FFC321;
  right: 0.6rem;
  width: 3rem;
  height: 2.6rem;
  text-align: center;
  text-transform: uppercase;
  color: white;
  font-weight: 700;
  line-height: 2rem;
  animation: 0.5s linear 1s infinite reverse flicker;
}

.vip::after {
  content: "";
  position: absolute;
  top: 1.6rem;
  right: 0.6rem;
  border: 1rem solid;
  border-width: 1rem 1.5rem;
  border-color: transparent #FFC321;
}

