}

.product1:hover, .product2:hover {
  box-shadow: #000000a8 0.2rem 0.4rem 1.2rem 0.2rem;
  transition: box-shadow 0.4s 0.1s;
}

.product1,.product2 > div {
  border: solid 0.063rem #2021242e;;
}

.product1-image {
  background: url(https://bizweb.dktcdn.net/thumb/grande/100/328/362/products/97493029.jpg?v=1534497006637) center / cover no-repeat;
  width: 100%;
  height: 15.525rem;
}
.product2-image {
  background: url(https://bizweb.dktcdn.net/thumb/grande/100/328/362/products/97493029.jpg?v=1534497006637) center / cover no-repeat;
  width: 100%;
  height: 15.525rem;
}

.product3-image {
  background: url(https://bizweb.dktcdn.net/thumb/grande/100/328/362/products/97493029.jpg?v=1534497006637) center / cover no-repeat;
  width: 100%;
  height: 15.525rem;
}

.product1-conntent {
  padding: 1.2rem 1.2rem 0.8rem;
}

.product1-conntent-header > a {
  color: var(--color-text);
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.03rem;
}

.product1-conntent-header > a:hover {
  color: var(--primary-color);
}

.product1-conntent-title {
  font-size: 0.9rem;
  font-weight: 400;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  padding-top: 0.7rem;
}

.product1-conntent-list {
  list-style-type: none;
  margin-bottom: 0;
  padding-left: 0;
}

.product1-conntent-item {
  font-size: 0.9rem;
  font-weight: 400;
  padding-bottom: 0.2rem;
}

.product1-conntent-item > svg {
  color: var(--primary-color);
  padding-right: 0.2rem;
  font-size: 0.8rem;
}

.product1-footer {
  padding: 0.8rem 1.2rem;
  display: flex;
  justify-content: space-between;
}

.product1-footer-cost {
  color: red;
  font-size: 1.2rem;
  font-weight: 700;
  cursor: default;
}

.product1-footer-detail {
  border: none;
  background-color: var(--primary-color);
  color: white;
  font-size: 0.9rem;
  padding: 0.4rem 1.2rem;
  border-radius: 0.4rem;
}

.content3-title {
  font-size: 2rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 6rem;
}

.content3 {
  margin: 0 auto 2rem;
}

.content3 .container {
  max-width: 1200px;
}

.content3-title:hover {
  color: var(--primary-color);
}

.product1-footer-detail:hover {
  background-color: #434A6E;
}


.product2 {
  width: 100%;
  margin-bottom: 2rem;
  border-radius: 0.5rem;
  overflow: hidden;
  background: #fff;
}

/* Keep cards in product sections aligned and avoid overlap when content length differs */
.content3-product .row {
  justify-content: center;
  --bs-gutter-x: 1.5rem;
  --bs-gutter-y: 1.5rem;
}

.content3-product .row > [class*="col-"] {
  display: flex;
  justify-content: center;
}

.content3-product .product2 {
  display: flex;
  flex-direction: column;
  height: 100%;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.content3-product .product2:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.15);
}

.content3-product .product1-conntent {
  flex: 1;
}

.content3-product .product1-footer {
  margin-top: auto;
  align-items: center;
}

.content3-product .product1-conntent-title {
  -webkit-line-clamp: 1;
}

.content3-product .product1-conntent-item {
  line-height: 1.4;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}

@media (min-width: 768px) {
  .content3-product .row > .col-md-3 {
    flex: 0 0 31%;
    max-width: 31%;
  }
}

.product2 > .product1-image {
  height: 11.4rem;
}

